"""
Bounded prefix-cache-aware dataframe reordering.

Rows are evaluated as concatenated serialized cell values.  This implementation
creates at most three data-preserving candidates and chooses the candidate with
the greatest exact serial-Trie reuse score:

1. Original column order.
2. Global length-weighted repeated-value ordering.
3. Row-specific conditional orders built from repeated serialized field values,
   with a bounded short-prefix fallback for distinct-but-similar values.

All source cells, rows, indices, and column labels are preserved.
"""

import heapq
from typing import List, Tuple

import numpy as np
import pandas as pd

from solver import Algorithm


class Evolved(Algorithm):
    """Build bounded column-permutation candidates for serial prefix reuse."""

    def __init__(self, df: pd.DataFrame = None):
        """Store an optional dataframe reference without modifying it."""
        self.df = df

    @staticmethod
    def _string_matrix(df: pd.DataFrame) -> np.ndarray:
        """Create evaluator-compatible temporary strings without changing df."""
        rows, cols = df.shape
        result = np.empty((rows, cols), dtype=object)

        for col in range(cols):
            series = df.iloc[:, col]
            try:
                result[:, col] = series.fillna("").astype(str).to_numpy(
                    dtype=object, copy=False
                )
            except (TypeError, ValueError):
                values = series.to_numpy(dtype=object, copy=False)
                converted = []
                for value in values:
                    try:
                        missing = pd.isna(value)
                        is_missing = isinstance(missing, (bool, np.bool_)) and bool(missing)
                    except (TypeError, ValueError):
                        is_missing = False
                    converted.append("" if is_missing else str(value))
                result[:, col] = converted

        return result

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Return character LCP using binary searched C-level slice equality."""
        limit = min(len(left), len(right))
        if limit == 0:
            return 0
        if left == right:
            return limit

        low, high = 0, limit
        while low < high:
            middle = (low + high + 1) // 2
            if left[:middle] == right[:middle]:
                low = middle
            else:
                high = middle - 1
        return low

    @classmethod
    def _reuse_score(cls, rows: List[str]) -> int:
        """Compute exact ideal serial-Trie reuse from sorted adjacent LCPs."""
        if len(rows) < 2:
            return 0
        ordered = sorted(rows)
        return sum(cls._lcp(ordered[i - 1], ordered[i]) for i in range(1, len(ordered)))

    @staticmethod
    def _serialize(strings: np.ndarray, orders: List[List[int]]) -> List[str]:
        """Serialize rows according to their individual source-column orders."""
        return [
            "".join(strings[row_id, order])
            for row_id, order in enumerate(orders)
        ]

    @staticmethod
    def _dependency_edges(columns, one_way_dep) -> List[Tuple[int, int]]:
        """Resolve unambiguous dependency declarations to source-position edges."""
        edges = []
        for dependency in one_way_dep or []:
            if not isinstance(dependency, (tuple, list)) or len(dependency) != 2:
                continue

            left_name, right_name = dependency
            left = [i for i, col in enumerate(columns) if str(left_name) in str(col)]
            right = [i for i, col in enumerate(columns) if str(right_name) in str(col)]

            if len(left) == 1 and len(right) == 1 and left[0] != right[0]:
                edges.append((left[0], right[0]))

        return edges

    @staticmethod
    def _apply_dependencies(order: List[int], edges: List[Tuple[int, int]]) -> List[int]:
        """Apply dependencies with a stable topological sort of a proposed order."""
        if not edges:
            return list(order)

        rank = {column: position for position, column in enumerate(order)}
        children = {column: [] for column in order}
        indegree = {column: 0 for column in order}

        for left, right in edges:
            if left in indegree and right in indegree:
                children[left].append(right)
                indegree[right] += 1

        ready = [(rank[col], col) for col in order if indegree[col] == 0]
        heapq.heapify(ready)
        result = []

        while ready:
            _, column = heapq.heappop(ready)
            result.append(column)
            for child in children[column]:
                indegree[child] -= 1
                if indegree[child] == 0:
                    heapq.heappush(ready, (rank[child], child))

        return result if len(result) == len(order) else list(order)

    @staticmethod
    def _merge_units(columns, col_merge) -> List[List[int]]:
        """Create non-overlapping units for requested adjacent merged columns."""
        used = set()
        units = []

        for group in col_merge or []:
            if not isinstance(group, (tuple, list)):
                continue

            positions = []
            valid = True

            for name in group:
                matches = [
                    i for i, column in enumerate(columns)
                    if column == name and i not in used
                ]
                if len(matches) != 1:
                    valid = False
                    break
                positions.append(matches[0])

            if valid and len(positions) > 1:
                units.append(positions)
                used.update(positions)

        for position in range(len(columns)):
            if position not in used:
                units.append([position])

        return units

    @staticmethod
    def _factorize(strings: np.ndarray, retain_codes: bool):
        """Factorize fields once and compute global repeated-value mass."""
        rows, cols = strings.shape
        codes = np.empty((rows, cols), dtype=np.int32) if retain_codes else None
        lengths = []
        scores = np.zeros(cols, dtype=np.int64)

        for col in range(cols):
            column_codes, unique_values = pd.factorize(strings[:, col], sort=False)
            column_codes = column_codes.astype(np.int32, copy=False)
            value_lengths = np.fromiter(
                (len(value) for value in unique_values),
                dtype=np.int64,
                count=len(unique_values),
            )
            counts = np.bincount(column_codes, minlength=len(unique_values)).astype(
                np.int64, copy=False
            )

            scores[col] = int(np.sum(value_lengths * counts * (counts - 1)))
            lengths.append(value_lengths)

            if retain_codes:
                codes[:, col] = column_codes

        return codes, lengths, scores

    @staticmethod
    def _prefix_codes(strings: np.ndarray, width: int = 8) -> np.ndarray:
        """Factorize short leading string prefixes for bounded fallback grouping."""
        rows, cols = strings.shape
        result = np.empty((rows, cols), dtype=np.int32)

        for col in range(cols):
            prefixes = np.fromiter(
                (value[:width] for value in strings[:, col]),
                dtype=object,
                count=rows,
            )
            result[:, col] = pd.factorize(prefixes, sort=False)[0].astype(
                np.int32, copy=False
            )

        return result

    def _global_order(self, scores, units, dependencies) -> List[int]:
        """Rank merge-safe units by length-weighted repeated-value mass."""
        ranked_units = sorted(
            units,
            key=lambda unit: (-sum(int(scores[col]) for col in unit), min(unit)),
        )

        proposal = []
        for unit in ranked_units:
            # Preserve explicit merged-group member order.
            if len(unit) > 1:
                proposal.extend(unit)
            else:
                proposal.extend(unit)

        return self._apply_dependencies(proposal, dependencies)

    @staticmethod
    def _local_repeat_score(row_ids, column, codes, lengths) -> int:
        """Return local count*(count-1) length-weighted exact repetition mass."""
        selected = codes[row_ids, column]
        if len(selected) < 2:
            return 0

        counts = np.bincount(selected).astype(np.int64, copy=False)
        return int(np.sum(lengths[column][:len(counts)] * counts * (counts - 1)))

    @staticmethod
    def _local_prefix_score(row_ids, column, prefix_codes) -> int:
        """Return cheap repeated short-prefix mass when whole values are unique."""
        selected = prefix_codes[row_ids, column]
        if len(selected) < 2:
            return 0

        counts = np.bincount(selected).astype(np.int64, copy=False)
        return int(np.sum(counts * (counts - 1)))

    def _conditional_orders(
        self,
        codes: np.ndarray,
        lengths,
        prefix_codes: np.ndarray,
        global_order: List[int],
        dependencies,
        row_stop,
        col_stop,
    ) -> List[List[int]]:
        """Build bounded row-specific orders from recursive value partitions."""
        rows, cols = codes.shape
        orders = [list(global_order) for _ in range(rows)]

        if rows < 2 or cols < 2:
            return orders

        depth_limit = min(cols, 10)
        for limit in (row_stop, col_stop):
            if limit is not None:
                try:
                    depth_limit = min(depth_limit, max(1, int(limit)))
                except (TypeError, ValueError):
                    pass

        candidate_cap = min(cols, 32)
        max_nodes = 192
        rank = {column: position for position, column in enumerate(global_order)}
        stack = [(np.arange(rows, dtype=np.int64), [], 0)]
        nodes = 0

        while stack and nodes < max_nodes:
            row_ids, prefix, depth = stack.pop()
            nodes += 1

            if len(row_ids) < 2 or depth >= depth_limit:
                continue

            used = set(prefix)
            remaining = [column for column in global_order if column not in used]
            remaining = remaining[:candidate_cap]

            if not remaining:
                continue

            best_column = None
            best_score = 0

            for column in remaining:
                score = self._local_repeat_score(row_ids, column, codes, lengths)
                if (
                    score > best_score
                    or (
                        score == best_score
                        and best_column is not None
                        and rank[column] < rank[best_column]
                    )
                ):
                    best_column = column
                    best_score = score

            # Distinct values can still share useful serialized prefixes.
            use_prefix_codes = best_score <= 0 and prefix_codes is not None
            if use_prefix_codes:
                for column in remaining:
                    score = self._local_prefix_score(row_ids, column, prefix_codes)
                    if (
                        score > best_score
                        or (
                            score == best_score
                            and best_column is not None
                            and rank[column] < rank[best_column]
                        )
                    ):
                        best_column = column
                        best_score = score

            if best_column is None or best_score <= 0:
                continue

            next_prefix = prefix + [best_column]
            chosen = set(next_prefix)
            local_order = next_prefix + [
                column for column in global_order if column not in chosen
            ]
            local_order = self._apply_dependencies(local_order, dependencies)

            for row_id in row_ids:
                orders[int(row_id)] = local_order

            grouping_codes = (
                prefix_codes[row_ids, best_column]
                if use_prefix_codes
                else codes[row_ids, best_column]
            )

            sorting = np.argsort(grouping_codes, kind="stable")
            grouped_rows = row_ids[sorting]
            grouped_codes = grouping_codes[sorting]

            start = 0
            while start < len(grouped_rows):
                end = start + 1
                while end < len(grouped_rows) and grouped_codes[end] == grouped_codes[start]:
                    end += 1

                if end - start > 1:
                    stack.append((grouped_rows[start:end], next_prefix, depth + 1))

                start = end

        return orders

    @staticmethod
    def _materialize(df: pd.DataFrame, orders: List[List[int]]) -> pd.DataFrame:
        """Apply row-specific permutations while retaining original cell objects."""
        source = df.to_numpy(dtype=object, copy=True)
        rows, cols = source.shape
        output = np.empty((rows, cols), dtype=object)

        for row_id, order in enumerate(orders):
            output[row_id, :] = source[row_id, order]

        return pd.DataFrame(
            output,
            index=df.index.copy(),
            columns=df.columns.copy(),
        )

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge: List[List[str]] = [],
        one_way_dep: List[Tuple[str, str]] = [],
        distinct_value_threshold: float = 0.8,
        parallel: bool = True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Return the highest exact-Trie-score bounded candidate permutation."""
        rows, cols = df.shape
        columns = list(df.columns)

        if rows == 0 or cols == 0:
            return df.copy(), [[] for _ in range(rows)]

        strings = self._string_matrix(df)
        units = self._merge_units(columns, col_merge)
        dependencies = self._dependency_edges(columns, one_way_dep)
        has_merge_constraint = any(len(unit) > 1 for unit in units)

        # Keep memory bounded because conditional candidates retain dense codes.
        retain_codes = not has_merge_constraint and rows * cols <= 10_000_000

        codes, lengths, frequency_scores = self._factorize(strings, retain_codes)
        global_order = self._global_order(frequency_scores, units, dependencies)

        candidates = []

        if not dependencies and not has_merge_constraint:
            identity = list(range(cols))
            candidates.append([list(identity) for _ in range(rows)])

        candidates.append([list(global_order) for _ in range(rows)])

        if codes is not None:
            prefix_codes = self._prefix_codes(strings) if rows * cols <= 6_000_000 else None
            candidates.append(
                self._conditional_orders(
                    codes,
                    lengths,
                    prefix_codes,
                    global_order,
                    dependencies,
                    row_stop,
                    col_stop,
                )
            )

        best_orders = candidates[0]
        best_score = -1

        for candidate in candidates:
            score = self._reuse_score(self._serialize(strings, candidate))
            if score > best_score:
                best_score = score
                best_orders = candidate

        reordered = self._materialize(df, best_orders)
        column_orderings = [
            [columns[position] for position in order]
            for order in best_orders
        ]

        return reordered, column_orderings

